          "headline": "Hegseth seeks roughly $50 billion in reconciliation funding to scale autonomous and robotic systems",
          "sources": [
            { "name": "C4ISRNET", "url": "https://www.c4isrnet.com/news/pentagon-congress/2026/10/14/pentagon-needs-50b-for-mass-drone-production-hegseth-says/" },
